package com.singtel.customerservice;import org.springframework.context.annotation.Profile;import org.springframework.stereotype.Component;import org.springframework.boot.CommandLineRunner;import java.math.BigDecimal;
@Component @Profile("local") public class SyntheticData implements CommandLineRunner{private final CustomerRepository repo;public SyntheticData(CustomerRepository r){repo=r;}public void run(String...args){if(repo.count()>0)return;for(int i=0;i<48;i++){var c=new Customer();c.id="C"+String.format("%05d",i+1);c.name="Synthetic customer "+(i+1);c.segment=i%3==0?"Prepaid":"Postpaid";c.plan=i%2==0?"5G SIM Only Premium":"5G SIM Only Plus";c.channel="My Singtel";c.region="Singapore";c.spend=BigDecimal.valueOf(40+i*3);c.newCustomer=i%4==0;c.consent=i%5!=0;repo.save(c);}}}
